-- ==========================================
-- ESP LINE V2 - DIRECT SOURCE SNAPLINE BRIDGE
-- Menggunakan PlayerMapMarker dari BRPlayerCharacterBase(3).lua
-- agar koordinat garis benar-benar sama dengan ESP source.
-- ==========================================

-- ==========================================================
-- ESP LINE V2 DIRECT RENDERER
-- Không phụ thuộc vào việc widget ESP đầu được tạo thành công.
-- Line luôn được tạo trực tiếp trên ESPCanvas và bám vào HEAD.
-- ==========================================================
_G.ESPLineV2Direct = _G.ESPLineV2Direct or {
    Lines = {},
    Canvas = nil,
}

function _G.ESPLineV2Direct.GetCanvas()
    local ok, UITools = pcall(require, "GameLua.Mod.BaseMod.Common.UI.InGameUITools")
    if not ok or not UITools then return nil end
    local ui = nil
    pcall(function()
        ui = UITools.GetMainControlBaseUI and UITools.GetMainControlBaseUI()
    end)
    if not ui then return nil end

    local c = nil
    pcall(function()
        if ui.CanvasPanel_0 and slua.isValid(ui.CanvasPanel_0) then c = ui.CanvasPanel_0 end
    end)
    if not c then
        pcall(function()
            if ui.CanvasPanel_42 and slua.isValid(ui.CanvasPanel_42) then c = ui.CanvasPanel_42 end
        end)
    end
    _G.ESPLineV2Direct.Canvas = c
    return c
end

function _G.ESPLineV2Direct.Remove(key)
    local d = _G.ESPLineV2Direct.Lines[key]
    if d then
        pcall(function()
            if d.Widget and slua.isValid(d.Widget) then
                d.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                d.Widget:RemoveFromParent()
                d.Widget:ConditionalBeginDestroy()
            end
        end)
        pcall(function()
            if d.NameWidget and slua.isValid(d.NameWidget) then
                d.NameWidget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                d.NameWidget:RemoveFromParent()
                d.NameWidget:ConditionalBeginDestroy()
            end
        end)
        pcall(function()
            if d.NameBorder and slua.isValid(d.NameBorder) then
                d.NameBorder:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                d.NameBorder:RemoveFromParent()
                d.NameBorder:ConditionalBeginDestroy()
            end
        end)
    end
    _G.ESPLineV2Direct.Lines[key] = nil
end

function _G.ESPLineV2Direct.Clear()
    for k,_ in pairs(_G.ESPLineV2Direct.Lines) do
        _G.ESPLineV2Direct.Remove(k)
    end
end

function _G.ESPLineV2Direct.Update(pc, localPlayer, targets)
    local canvas = _G.ESPLineV2Direct.GetCanvas()
    if not canvas then return false end

    local vw, vh = 1920, 1080
    pcall(function()
        local v = pc:GetViewportSize(FVector2D(0,0))
        if v and v.X and v.X > 200 then vw, vh = v.X, v.Y end
    end)
    pcall(function()
        if WidgetLayoutLibrary and WidgetLayoutLibrary.GetViewportSize then
            local v = WidgetLayoutLibrary.GetViewportSize(pc)
            if v and v.X and v.X > 200 then vw, vh = v.X, v.Y end
        end
    end)

    -- Sama seperti screenshot: line berasal dari bagian atas-tengah layar.
    local fromX, fromY = vw * 0.5, 42
    local seen = {}

    for key, enemy in pairs(targets or {}) do
        if enemy and slua.isValid(enemy) then
            local loc = nil
            pcall(function() loc = PlayerMapMarker.GetESPLocation(enemy) end)

            if loc then
                local onScreen, pos = false, nil
                pcall(function()
                    onScreen, pos = PlayerMapMarker.ProjectWorldToCanvasLocal(pc, loc)
                end)

                if onScreen and pos then
                    seen[key] = true
                    local d = _G.ESPLineV2Direct.Lines[key]

                    if not d or not d.Widget or not slua.isValid(d.Widget) then
                        local b = nil
                        pcall(function()
                            b = CGame:NewObjectFromPath("/Script/UMG.Border", canvas)
                        end)
                        if b then
                            pcall(function()
                                b:SetBrushColor(FLinearColor(0.0, 1.0, 0.0, 0.95))
                                b:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                                b:SetRenderOpacity(0.95)
                                b:SetRenderTransformPivot(FVector2D(0.0, 0.5))
                            end)
                            local slot = nil
                            pcall(function()
                                slot = canvas:AddChildToCanvas(b)
                                if slot then
                                    slot:SetAutoSize(false)
                                    slot:SetZOrder(999)
                                end
                            end)
                            if slot then
                                d = {Widget=b, Slot=slot}
                                _G.ESPLineV2Direct.Lines[key] = d
                            end
                        end
                    end

                    if d and d.Widget and d.Slot then
                        -- Endpoint tepat di kepala.
                        local tx = pos.X
                        local ty = pos.Y - 12
                        local dx = tx - fromX
                        local dy = ty - fromY
                        local len = math.sqrt(dx*dx + dy*dy)
                        if len < 1 then len = 1 end
                        local ang = math.deg(math.atan2(dy, dx))

                        pcall(function()
                            d.Slot:SetPosition(FVector2D(fromX, fromY))
                            d.Slot:SetSize(FVector2D(len, 3.0))
                            d.Slot:SetZOrder(999)
                            d.Widget:SetRenderAngle(ang)
                            d.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                        end)

                        -- ==================================================
                        -- NAMA + JARAK DI ATAS KEPALA
                        -- Contoh: GODMOD | EnemyName [125m]
                        -- ==================================================
                        local name = "Enemy"
                        pcall(function()
                            local n = PlayerMapMarker.GetPlayerName(enemy)
                            if n and tostring(n) ~= "" then name = tostring(n) end
                        end)

                        local myLoc = nil
                        pcall(function() myLoc = localPlayer:K2_GetActorLocation() end)
                        local dist = 0
                        if myLoc and loc then
                            pcall(function()
                                dist = math.floor((myLoc - loc):Size() / 100 + 0.5)
                            end)
                        end
                        local label = string.format("GODMOD | %s [%dm]", name, dist)

                        if not d.NameWidget or not slua.isValid(d.NameWidget) then
                            local tw = nil
                            pcall(function()
                                tw = CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas)
                            end)
                            if tw then
                                local ts = nil
                                pcall(function()
                                    ts = canvas:AddChildToCanvas(tw)
                                    if ts then
                                        ts:SetAutoSize(true)
                                        ts:SetZOrder(1000)
                                    end
                                end)
                                if ts then
                                    d.NameWidget = tw
                                    d.NameSlot = ts
                                    pcall(function()
                                        tw:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                                        tw:SetRenderOpacity(1.0)
                                        tw:SetJustification(1)
                                        tw:SetText(label)
                                        tw:SetFont(FSlateFontInfo and FSlateFontInfo("/Script/Engine.Font", 13) or nil)
                                        tw:SetColorAndOpacity(FLinearColor(0.8, 1.0, 0.2, 1.0))
                                    end)
                                end
                            end
                        end

                        if d.NameWidget and d.NameSlot then
                            pcall(function()
                                d.NameWidget:SetText(label)
                                d.NameSlot:SetPosition(FVector2D(tx - 90, ty - 25))
                                d.NameSlot:SetZOrder(1000)
                                d.NameWidget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                            end)
                        end
                    end
                end
            end
        end
    end

    for key,_ in pairs(_G.ESPLineV2Direct.Lines) do
        if not seen[key] then
            _G.ESPLineV2Direct.Remove(key)
        end
    end
    return true
end

_G.ESPLineV2Overlay = _G.ESPLineV2Overlay or {}

local function ESPLineV2BuildPlayers(localPlayer, maxDist)
    local out = {}
    local all = {}
    pcall(function()
        if GameplayData.GetAllPlayerCharacters then
            all = GameplayData.GetAllPlayerCharacters() or {}
        elseif GameplayData.GameCharacters then
            for _,ch in pairs(GameplayData.GameCharacters) do table.insert(all,ch) end
        end
    end)
    for _, enemy in pairs(all) do
        if slua.isValid(enemy) and enemy ~= localPlayer then
            local alive = true
            pcall(function() if enemy.IsAlive then alive = enemy:IsAlive() end end)
            if alive then
                local dist = nil
                pcall(function() if localPlayer.GetDistanceTo then dist = localPlayer:GetDistanceTo(enemy) end end)
                if dist and dist <= (maxDist * 100.0) then
                    local key = nil
                    pcall(function() if enemy.GetUniqueID then key=tostring(enemy:GetUniqueID()) end end)
                    key = key or tostring(enemy)
                    out[key] = enemy
                end
            end
        end
    end
    return out
end

function _G.ESPLineV2Overlay.HideAll()
    pcall(function() if _G.ESPLineV2Direct then _G.ESPLineV2Direct.Clear() end end)
    pcall(function()
        if _G.PlayerMapMarker then
            _G.PlayerMapMarker.bUseSnapLines = false
            _G.PlayerMapMarker.bUseScreenESP = false
            _G.PlayerMapMarker.ClearAllSnapLines()
            _G.PlayerMapMarker.ClearAllESP()
        end
    end)
end

function _G.ESPLineV2Overlay.Update(pc, localPlayer)
    local cfg = _G.GODMODConfig or {}
    if not cfg.EspLineV2 then
        _G.ESPLineV2Overlay.HideAll()
        return
    end
    if not slua.isValid(pc) or not slua.isValid(localPlayer) then return end
    if not _G.PlayerMapMarker then return end

    local maxDist = tonumber(cfg.EspLineV2MaxDistance) or 400
    if maxDist < 10 then maxDist = 10 end
    if maxDist > 500 then maxDist = 500 end

    -- Sinkronkan V2 ke renderer SnapLine asli.
    _G.PlayerMapMarker.bUseScreenESP = true
    _G.PlayerMapMarker.bUseSnapLines = true
    _G.PlayerMapMarker.bUseSkeleton = false
    _G.PlayerMapMarker.bIncludeMe = false
    _G.PlayerMapMarker.bIncludeAI = true

    -- Aktifkan text jarak di atas target.
    _G.LexusConfig = _G.LexusConfig or {}
    _G.LexusConfig.Esp9_Line = true
    _G.LexusConfig.Esp9_Distance = true
    _G.LexusConfig.Esp9_Name = false

    local chars = ESPLineV2BuildPlayers(localPlayer, maxDist)
    local myLoc = nil
    pcall(function() myLoc = localPlayer:K2_GetActorLocation() end)
    if not myLoc then return end

    -- Renderer langsung: line dibuat sendiri sehingga tidak tergantung ESP head widget.
    pcall(function()
        _G.ESPLineV2Direct.Update(pc, localPlayer, chars)
    end)

    -- Renderer PlayerMapMarker tetap dijalankan untuk teks jarak/head ESP.
    pcall(function()
        _G.PlayerMapMarker.UpdateESP(chars, myLoc)
        _G.PlayerMapMarker.UpdateESPDistances()
    end)

    -- Hapus target lama yang berada di luar radius V2.
    pcall(function()
        for key, data in pairs(_G.PlayerMapMarker.ESPWidgets or {}) do
            if not chars[key] then
                _G.PlayerMapMarker.RemoveSnapLine(key)
                _G.PlayerMapMarker.RemoveESPWidget(data.Widget, key)
                _G.PlayerMapMarker.ESPWidgets[key] = nil
            end
        end
    end)
end

function _G.CleanUpESPLineV2Overlay()
    pcall(function() if _G.ESPLineV2Direct then _G.ESPLineV2Direct.Clear() end end)
    pcall(function()
        if _G.PlayerMapMarker then
            _G.PlayerMapMarker.bUseSnapLines = false
            _G.PlayerMapMarker.ClearAllSnapLines()
        end
    end)
end

-- FOV CIRCLE OVERLAY (MANDIRI, TANPA PLAYERMAPMARKER - FIXED SYNC)
-- ==========================================
local SlateBlueprintLibrary = import("SlateBlueprintLibrary")

_G.FovCircleOverlay = {
    Container = nil,
    WidgetSlot = nil,
    ParentCanvas = nil,
    Lines = {},
    NumSegments = 45,
    Thickness = 1.5,
    LastRadius = -1,
    LastColor = -1,
    LastCX = -1,
    LastCY = -1,
    PrecalcMath = nil
}

local function GetFOVColor(idx)
    if idx == 1 then return 1.0, 0.0, 0.0 end
    if idx == 2 then return 0.0, 1.0, 0.0 end
    if idx == 3 then return 0.0, 0.0, 1.0 end
    if idx == 4 then return 1.0, 1.0, 0.0 end
    if idx == 5 then return 0.65, 0.15, 1.0 end
    if idx == 6 then return 0.0, 1.0, 1.0 end
    if idx == 7 then return 1.0, 1.0, 1.0 end
    return 1.0, 1.0, 1.0
end

function _G.FovCircleOverlay.Create()
    if _G.FovCircleOverlay.Container and slua.isValid(_G.FovCircleOverlay.Container) then
        return true
    end

    local ParentCanvas = nil
    pcall(function()
        local InGameUITools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
        local MainUI = InGameUITools.GetMainControlBaseUI()
        if slua.isValid(MainUI) then
            if slua.isValid(MainUI.CanvasPanel_0) then
                ParentCanvas = MainUI.CanvasPanel_0
            elseif slua.isValid(MainUI.CanvasPanel_42) then
                ParentCanvas = MainUI.CanvasPanel_42
            end
        end
    end)

    if not ParentCanvas or not slua.isValid(ParentCanvas) then
        return false
    end

    local Container = nil
    pcall(function()
        Container = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", ParentCanvas)
    end)
    if not Container or not slua.isValid(Container) then
        return false
    end

    local FVector2D = import("Vector2D") or _G.FVector2D

    for i = 1, _G.FovCircleOverlay.NumSegments do
        local border = nil
        pcall(function()
            border = CGame:NewObjectFromPath("/Script/UMG.Border", Container)
        end)
        if border and slua.isValid(border) then
            pcall(function()
                border.RenderTransformPivot = FVector2D(0, 0.5)
                border:SetRenderTransformPivot(FVector2D(0, 0.5))
                border:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            end)
            local slot = Container:AddChildToCanvas(border)
            if slot then
                pcall(function()
                    slot:SetAlignment(FVector2D(0, 0.5))
                end)
            end
            _G.FovCircleOverlay.Lines[i] = { widget = border, slot = slot }
        end
    end

    local MainSlot = nil
    pcall(function()
        MainSlot = ParentCanvas:AddChildToCanvas(Container)
    end)
    if MainSlot then
        pcall(function()
            MainSlot:SetAutoSize(false)
            MainSlot:SetSize(FVector2D(0, 0))
            MainSlot:SetZOrder(995)
            MainSlot:SetAlignment(FVector2D(0, 0))
            MainSlot:SetPosition(FVector2D(0, 0))
        end)
    end

    _G.FovCircleOverlay.Container = Container
    _G.FovCircleOverlay.WidgetSlot = MainSlot
    _G.FovCircleOverlay.ParentCanvas = ParentCanvas
    return true
end

function _G.FovCircleOverlay.Update(pc, player)
    if not _G.GODMODConfig.EspFovCircle then
        if _G.FovCircleOverlay.Container and slua.isValid(_G.FovCircleOverlay.Container) then
            pcall(function()
                _G.FovCircleOverlay.Container:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
            end)
            _G.FovCircleOverlay.LastRadius = -1
        end
        return
    end

    local fovVal = 30
    local colIdx = 7
    local cData = _G.GODMODState.CustomTextData
    local WEAPON_TYPE = _G.__AimTouch_WeaponType or "NORMAL"
    local isADS = player.bIsGunADS or false

    if WEAPON_TYPE == "MORTAR" then
        fovVal = cData.AimTouchMortarFOV or 360
        colIdx = tonumber(cData.AimTouchMortarFOVColor) or 5
    elseif WEAPON_TYPE == "SHOTGUN" then
        fovVal = cData.AimTouchSGFOV or 40
        colIdx = tonumber(cData.AimTouchSGFOVColor) or 1
    elseif isADS then
        if WEAPON_TYPE == "SNIPER" then
            fovVal = cData.AimTouchSniperFOV or 20
            colIdx = tonumber(cData.AimTouchSniperFOVColor) or 4
        else
            fovVal = cData.AimTouchScopeFOV or 30
            colIdx = tonumber(cData.AimTouchScopeFOVColor) or 6
        end
    else
        fovVal = cData.AimTouchHipFOV or 30
        colIdx = tonumber(cData.AimTouchHipFOVColor) or 7
    end

    local rawCX = _G.__AimTouch_CenterX or 960
    local rawCY = _G.__AimTouch_CenterY or 540
    local vpX = _G.__AimTouch_ViewportX or 1920

    if not _G.FovCircleOverlay.Create() then
        return
    end

    local ParentCanvas = _G.FovCircleOverlay.ParentCanvas
    if not ParentCanvas or not slua.isValid(ParentCanvas) then
        return
    end

    -- Hitung transformasi Canvas dengan SlateBlueprintLibrary
    local scaleX, scaleY, offsetX, offsetY = 1.0, 1.0, 0.0, 0.0
    pcall(function()
        local cg = ParentCanvas:GetCachedGeometry()
        if cg and SlateBlueprintLibrary then
            local FVector2D = import("Vector2D") or _G.FVector2D
            local pt0 = SlateBlueprintLibrary.AbsoluteToLocal(cg, FVector2D(0, 0))
            local pt1 = SlateBlueprintLibrary.AbsoluteToLocal(cg, FVector2D(100, 100))
            if pt0 and pt1 then
                scaleX = (pt1.X - pt0.X) / 100
                scaleY = (pt1.Y - pt0.Y) / 100
                offsetX = pt0.X
                offsetY = pt0.Y
            end
        end
    end)

    -- Konversi titik tengah layar ke koordinat Canvas (agar pas di crosshair)
    local centerX = rawCX * scaleX + offsetX
    local centerY = rawCY * scaleY + offsetY

    -- Radius dalam pixel layar, lalu diskalakan ke Canvas
    local avgScale = (scaleX + scaleY) / 2
    local rawRadius = (fovVal / 100.0) * (vpX / 2.0)
    local targetRadius = rawRadius * avgScale

    if math.abs(_G.FovCircleOverlay.LastRadius - targetRadius) < 0.5
       and _G.FovCircleOverlay.LastColor == colIdx
       and math.abs(_G.FovCircleOverlay.LastCX - centerX) < 0.5
       and math.abs(_G.FovCircleOverlay.LastCY - centerY) < 0.5 then
        return
    end

    _G.FovCircleOverlay.LastRadius = targetRadius
    _G.FovCircleOverlay.LastColor = colIdx
    _G.FovCircleOverlay.LastCX = centerX
    _G.FovCircleOverlay.LastCY = centerY

    pcall(function()
        _G.FovCircleOverlay.Container:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
    end)

    local FLinearColor = import("LinearColor") or _G.FLinearColor
    local r, g, b = GetFOVColor(colIdx)
    local dim = 0.55
    local color = FLinearColor and FLinearColor(r * dim, g * dim, b * dim, 1.0)
        or {R = r * dim * 255, G = g * dim * 255, B = b * dim * 255, A = 255}

    local numSegments = _G.FovCircleOverlay.NumSegments

    if not _G.FovCircleOverlay.PrecalcMath then
        _G.FovCircleOverlay.PrecalcMath = {}
        local angleStep = 360.0 / numSegments
        local math_cos = math.cos
        local math_sin = math.sin
        local math_rad = math.rad
        local math_atan2 = math.atan2 or math.atan

        for i = 1, numSegments do
            local angle1 = math_rad((i - 1) * angleStep)
            local angle2 = math_rad(i * angleStep)
            local c1, s1 = math_cos(angle1), math_sin(angle1)
            local c2, s2 = math_cos(angle2), math_sin(angle2)
            local dx_unit = c2 - c1
            local dy_unit = s2 - s1
            local dist_unit = math.sqrt(dx_unit * dx_unit + dy_unit * dy_unit)
            local angleDeg = math.deg(math_atan2(dy_unit, dx_unit))
            _G.FovCircleOverlay.PrecalcMath[i] = {
                c1 = c1, s1 = s1,
                dist_unit = dist_unit,
                angleDeg = angleDeg
            }
        end
    end

    pcall(function()
        local FVector2D = import("Vector2D") or _G.FVector2D
        for i = 1, numSegments do
            local mathData = _G.FovCircleOverlay.PrecalcMath[i]
            local x1 = targetRadius * mathData.c1
            local y1 = targetRadius * mathData.s1
            local dist = targetRadius * mathData.dist_unit

            local line = _G.FovCircleOverlay.Lines[i]
            if line and line.slot and slua.isValid(line.slot) then
                line.slot:SetPosition(FVector2D(centerX + x1, centerY + y1))
                line.slot:SetSize(FVector2D(dist + 0.8, _G.FovCircleOverlay.Thickness))
                line.widget:SetRenderAngle(mathData.angleDeg)
                line.widget:SetBrushColor(color)
            end
        end
    end)
end

