                _G.GODMODState.MagicUpdateVersion = (_G.GODMODState.MagicUpdateVersion or 0) + 1
                _G.GODMODState.LastMagicConfigHash = currentMagicHash
            end
        else
            if _G.GODMODState.LastMagicConfigHash ~= "OFF" then
